from .si_unit import prefix_to_exp, prefix_to_symbol, unit_to_symbol, unit_to_type


# Gender mapping based on Wiktionary's Module:gender_and_number
_GENDER_MAPPING = {
    # Genders
    "m": "masculine",
    "f": "feminine", 
    "n": "neuter",
    "c": "common gender",
    # Numbers
    "s": "singular",
    "p": "plural",
    # Animacy
    "an": "animate",
    "in": "inanimate",
    # Other qualifiers
    "impf": "imperfective",
    "pf": "perfective",
}


def parse_gender(gender_str: str) -> str:
    """
    Parse a Wiktionary gender/number string into a human-readable format.

    Examples:
        "m" -> "masculine"
        "f-p" -> "feminine plural"
        "m-f" -> "masculine or feminine"
        "n-p" -> "neuter plural"
    """
    if not gender_str:
        return ""

    # Handle "or" combinations (separated by hyphens)
    if "-" in gender_str and not gender_str.startswith("-") and not gender_str.endswith("-"):
        parts = gender_str.split("-")
        if len(parts) == 2:
            # Special case: m-f, f-m should be "masculine or feminine"
            if set(parts) == {"m", "f"}:
                return "masculine or feminine"
            elif set(parts) == {"f", "m"}:
                return "feminine or masculine"

            # General case: parse each part and join with "or"
            parsed_parts = []
            for part in parts:
                if part in _GENDER_MAPPING:
                    parsed_parts.append(_GENDER_MAPPING[part])
                else:
                    parsed_parts.append(part)
            return " or ".join(parsed_parts)

    # Handle regular single codes or other combinations
    if gender_str in _GENDER_MAPPING:
        return _GENDER_MAPPING[gender_str]

    # For unknown codes, return as-is but try to parse compound forms
    # Handle cases like "m-p", "f-s", etc.
    if "-" in gender_str:
        parts = [part for part in gender_str.split("-") if part]
        parsed_parts = []
        for part in parts:
            if part in _GENDER_MAPPING:
                parsed_parts.append(_GENDER_MAPPING[part])
            else:
                parsed_parts.append(part)
        return " ".join(parsed_parts)

    # Return as-is for unrecognized codes
    return gender_str


